export function runUntrack(run: GitRunner, log: (m: string) => void, err: (m: string) => void): number {
  try {
    const { before } = untrackAndVerify(run);
    log(`untracked ${before} paths`);
    return 0;
  } catch (e) {
    err(e instanceof Error ? e.message : String(e));
    return 1;
  }
}
